import{_ as a,o,c as l,a3 as t}from"./chunks/framework.D3oaa6bG.js";const p=JSON.parse('{"title":"Console commands","description":"","frontmatter":{},"headers":[],"relativePath":"development/core/console-commands.md","filePath":"development/core/console-commands.md","lastUpdated":null}'),n={name:"development/core/console-commands.md"};function s(d,e,r,c,i,m){return o(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="console-commands" tabindex="-1">Console commands <a class="header-anchor" href="#console-commands" aria-label="Permalink to &quot;Console commands&quot;">​</a></h1><h2 id="mall-check" tabindex="-1"><code>mall:check</code> <a class="header-anchor" href="#mall-check" aria-label="Permalink to &quot;`mall:check`&quot;">​</a></h2><p>The <code>php artisan mall:check</code> console command runs a set of checks on your October installation and makes sure that everything is configured correctly. It also supports you in fixing any problems that were found.</p><h2 id="mall-seed-demo" tabindex="-1"><code>mall:seed-demo</code> <a class="header-anchor" href="#mall-seed-demo" aria-label="Permalink to &quot;`mall:seed-demo`&quot;">​</a></h2><p>The <code>php artisan mall:seed-demo</code> command will populate your installation with demo data.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This will erase all shop data and reset all settings! Do not run this command if you have already configured your installation.</p></div><h2 id="mall-purge" tabindex="-1"><code>mall:purge</code> <a class="header-anchor" href="#mall-purge" aria-label="Permalink to &quot;`mall:purge`&quot;">​</a></h2><p>The <code>php artisan mall:purge</code> command will remove all order and customer data from your installation. Products, Variants and your Settings will remain untouched. This command essentially brings the installation back to the state it had before the first customer created an account.</p><p>The command is useful to revert back to a clean slate once you&#39;ve installed and tested your wn-mall-plugin installation on a production system.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This will erase all order and customer data! Do not run this command if you have already opened your shop up to the public.</p></div><h2 id="mall-index" tabindex="-1"><code>mall:index</code> <a class="header-anchor" href="#mall-index" aria-label="Permalink to &quot;`mall:index`&quot;">​</a></h2><p>The <code>php artisan mall:index</code> command re-indexes all your product data and fixes a corrupted product index.</p><p>You will notice a corrupted index if your category listing shows outdated data or the product filters are not working as expected.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>During the re-indexing process your frontend will be wiped clean and only show already re-indexed products. A re-indexing of a small installation will only take a few seconds. Be aware that this process might take a few minutes if you re-index a huge catalogue with thousands of products.</p></div>',14)])])}const h=a(n,[["render",s]]);export{p as __pageData,h as default};
